import{_ as e,o as r,c as a,ae as o}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"Mock Data 與最小維護","description":"","frontmatter":{},"headers":[],"relativePath":"product/mock-data.md","filePath":"product/mock-data.md"}'),d={name:"product/mock-data.md"};function s(n,t,i,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="mock-data-與最小維護" tabindex="-1">Mock Data 與最小維護 <a class="header-anchor" href="#mock-data-與最小維護" aria-label="Permalink to &quot;Mock Data 與最小維護&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件描述 Mock 資料策略與最小維護開發原則：現況、種子資料、可選 MSW。</p><hr><h2 id="現況-資料來源一覽" tabindex="-1">現況：資料來源一覽 <a class="header-anchor" href="#現況-資料來源一覽" aria-label="Permalink to &quot;現況：資料來源一覽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>範圍</th><th>儲存方式</th><th>重啟後</th><th>說明</th></tr></thead><tbody><tr><td><strong>Items API</strong></td><td>in-memory 陣列</td><td>清空</td><td><code>mock-items.server.ts</code> 內建 2 筆種子（alpha, beta）</td></tr><tr><td><strong>Dish</strong></td><td>in-memory Map</td><td>清空</td><td>無種子</td></tr><tr><td><strong>Recipe</strong></td><td>in-memory Map</td><td>清空</td><td>無種子</td></tr><tr><td><strong>Ingredient</strong></td><td>in-memory Map</td><td>清空</td><td>無種子</td></tr><tr><td><strong>Vendor</strong></td><td>in-memory Map + DishVendor Map</td><td>清空</td><td>無種子</td></tr><tr><td><strong>Release Notes</strong></td><td>檔案 <code>content/release-notes.json</code></td><td>保留</td><td>有則讀取，無則空陣列</td></tr><tr><td><strong>LUI 回答</strong></td><td>無狀態 mock 函式</td><td>-</td><td><code>lui.server.ts</code> 固定回傳範例</td></tr></tbody></table><hr><h2 id="最小維護開發原則" tabindex="-1">最小維護開發原則 <a class="header-anchor" href="#最小維護開發原則" aria-label="Permalink to &quot;最小維護開發原則&quot;">​</a></h2><ol><li><strong>不依賴外部 API</strong>：開發與演示以 in-memory / 檔案為準，無需後端服務即可跑滿流程。</li><li><strong>種子資料集中管理</strong>：領域種子（Ingredient / Dish / Recipe / Vendor）建議放在單一模組或 JSON，由各 feature server 啟動時載入（若為空才 seed），避免散落各處。</li><li><strong>Items API</strong>：維持現狀即可，作為通用 CRUD 範例與測試用。</li><li><strong>Release Notes</strong>：只改 <code>content/release-notes.json</code>，不改程式。</li><li><strong>LUI</strong>：目前 mock 回傳固定內容；未來若要接真實檢索/LLM，僅替換 <code>lui.server.ts</code> 實作，API 契約不變。</li></ol><hr><h2 id="種子資料-已實作" tabindex="-1">種子資料（已實作） <a class="header-anchor" href="#種子資料-已實作" aria-label="Permalink to &quot;種子資料（已實作）&quot;">​</a></h2><ul><li><strong>模組</strong>：<code>app/services/seed.server.ts</code> 的 <code>ensureSeeded()</code>。</li><li><strong>觸發</strong>：Root loader 每次請求時呼叫；函式內以 <code>seeded</code> 旗標僅執行一次（process 生命週期內）。</li><li><strong>內容</strong>：若 Ingredient Map 為空，則建立 2 筆原料（紅棗、枸杞）、1 筆 Dish（紅棗枸杞茶）、1 筆 Recipe、1 筆 Vendor（示範養生館）與一筆 DishVendor 關聯；營養與功效由既有 <code>nutrition.server</code> 計算。</li><li><strong>不覆寫</strong>：若已有 Ingredient 資料（例如測試注入），則直接 return，不寫入。</li></ul><hr><h2 id="msw-mock-service-worker" tabindex="-1">MSW（Mock Service Worker） <a class="header-anchor" href="#msw-mock-service-worker" aria-label="Permalink to &quot;MSW（Mock Service Worker）&quot;">​</a></h2><ul><li><strong>現況</strong>：<code>app/test/handlers.ts</code> 已註冊 Items API 等 handler，回傳經契約 schema parse。</li><li><strong>最小維護</strong>：單元測試可直接測 server 函式；E2E 或整合測試透過 MSW 隔離 API；新增 API 須同步新增 handler。</li></ul><h2 id="mock-dataset-版本化-資料治理變遷" tabindex="-1">Mock Dataset 版本化（資料治理變遷） <a class="header-anchor" href="#mock-dataset-版本化-資料治理變遷" aria-label="Permalink to &quot;Mock Dataset 版本化（資料治理變遷）&quot;">​</a></h2><ul><li><strong>目的</strong>：可回溯、可重現、可控變更；對應「資料治理」中的版本精神（見 <a href="./../architecture/data-governance.html">data-governance</a>）。</li><li><strong>約定</strong>：Mock 情境以 <code>app/test/datasets/v1/</code>、<code>v2/</code> 等版本管理；schema 或情境變更時新增版本並撰寫 <code>MIGRATION.md</code>，不直接覆寫舊 fixture；測試可指定 dataset version。</li><li><strong>現況</strong>：目前 fixture 仍寫在 handlers 內；目錄 <code>app/test/datasets/v1/</code> 已預留，可逐步將 fixture 遷出或由檔案載入。見 <a href="./../conventions/mock-dataset-versioning.html">mock-dataset-versioning</a>。</li></ul><hr><h2 id="相關文件" tabindex="-1">相關文件 <a class="header-anchor" href="#相關文件" aria-label="Permalink to &quot;相關文件&quot;">​</a></h2><ul><li>領域模型：<a href="./domain-food-recipe.html">domain-food-recipe</a></li><li>Items API：<a href="./items-api.html">items-api</a></li><li>LUI：<a href="./lui-search.html">lui-search</a></li><li>版號：<a href="./release-notes.html">release-notes</a></li><li>資料治理與 dataset 版本：<a href="./../architecture/data-governance.html">data-governance</a>、<a href="./../conventions/mock-dataset-versioning.html">mock-dataset-versioning</a></li></ul>',20)])])}const u=e(d,[["render",s]]);export{g as __pageData,u as default};
